</div>
<div id="stepBox" style="line-height:1.35;margin-top:3px;"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// left axes → Line segments black + ConeGeometry arrowheads
// tick marks → short Line segments black
// rotation axis → red Line spanning left graph and solid
// generating curve → sampled Line y=f(x), blue
// shaded region R → ShapeGeometry in z=0, translucent light blue
// x=2 boundary → dark vertical Line
// left washer → RingGeometry in YZ plane, gray translucent annulus
// sample segment → vertical Line from y=0 to y=f(x)
// rotation arrow → partial circular Line in YZ plane plus ConeGeometry arrowhead
// 3D outer solid → parametric BufferGeometry surface of revolution, blue-gray transparent
// 3D inner hole → cylindrical BufferGeometry surface, gray transparent
// end caps → annular BufferGeometry faces at x=0 and x=2, gray transparent
// rims → circular Line loops on cap boundaries
// highlighted 3D washer → annular BufferGeometry disk at selected x, warm gray translucent
// radius guides → colored Lines from rotation axis to y=0 and y=f(x)

const AXIS_COLOR = 0x222222;
const BLUE = 0x20a7df;
const FILL_BLUE = 0xbfe3f0;
const ROT_RED = 0xff5b63;
const SOLID_BLUE = 0xc8dce5;
const GRAY = 0xbfc3c6;
const DARK_GRAY = 0x55585c;
const HILITE = 0xd8d0c6;

scene.add(new THREE.AmbientLight(0xffffff, 0.72));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.75);
keyLight.position.set(3, 8, 8);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
fillLight.position.set(-4, 3, -6);
scene.add(fillLight);

let currentFn = (x) => x * x;
let currentExpr = 'x^2';
let cAxis = -1;
let sampleX = 1;
let labelsReady = false;
const labelRefs = {};

const staticGroup = new THREE.Group();
const dynamicGroup = new THREE.Group();
const solidGroup = new THREE.Group();
const sampleGroup = new THREE.Group();
scene.add(staticGroup, dynamicGroup, solidGroup, sampleGroup);

function disposeGroup(group) {
  while (group.children.length) {
    const obj = group.children.pop();
    obj.traverse?.((o) => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}

function safeF(x) {
  let y;
  try { y = currentFn(x); } catch { y = NaN; }
  return Number.isFinite(y) ? y : 0;
}

function makeLine(points, color = AXIS_COLOR, transparent = false, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, transparent, opacity });
  return new THREE.Line(geom, mat);
}

function addSegment(group, a, b, color = AXIS_COLOR, opacity = 1) {
  const line = makeLine([new THREE.Vector3(...a), new THREE.Vector3(...b)], color, opacity < 1, opacity);
  group.add(line);
  return line;
}

function addConeArrow(group, pos, dir, color = AXIS_COLOR, radius = 0.055, height = 0.18) {
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(radius, height, 24),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.set(...pos);
  const q = new THREE.Quaternion();
  q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  cone.quaternion.copy(q);
  group.add(cone);
  return cone;
}

function buildStaticElements() {
  addSegment(staticGroup, [-0.45, 0, 0], [2.55, 0, 0], AXIS_COLOR);
  addConeArrow(staticGroup, [2.63, 0, 0], new THREE.Vector3(1, 0, 0), AXIS_COLOR);
  addSegment(staticGroup, [0, -2.9, 0], [0, 4.65, 0], AXIS_COLOR);
  addConeArrow(staticGroup, [0, 4.74, 0], new THREE.Vector3(0, 1, 0), AXIS_COLOR);

  addSegment(staticGroup, [2, -0.09, 0], [2, 0.09, 0], AXIS_COLOR);
  addSegment(staticGroup, [-0.09, 4, 0], [0.09, 4, 0], AXIS_COLOR);

  addRotationArrow();
}

function addRotationArrow() {
  const cx = 3.55;
  const r = 0.45;
  const pts = [];
  for (let i = 0; i <= 56; i++) {
    const t = THREE.MathUtils.degToRad(-70 + 270 * i / 56);
    pts.push(new THREE.Vector3(cx, cAxis + r * Math.cos(t), r * Math.sin(t)));
  }
  const arc = makeLine(pts, AXIS_COLOR);
  staticGroup.add(arc);
  const end = pts[pts.length - 1];
  const tEnd = THREE.MathUtils.degToRad(200);
  const tangent = new THREE.Vector3(0, -Math.sin(tEnd), Math.cos(tEnd)).normalize();
  addConeArrow(staticGroup, [end.x, end.y, end.z], tangent, AXIS_COLOR, 0.045, 0.14);
}

function buildRegionAndCurve() {
  disposeGroup(dynamicGroup);

  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  const n = 100;
  for (let i = 0; i <= n; i++) {
    const x = 2 * i / n;
    shape.lineTo(x, safeF(x));
  }
  shape.lineTo(2, 0);
  shape.lineTo(0, 0);
  const region = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({
      color: FILL_BLUE,
      transparent: true,
      opacity: 0.55,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  region.position.z = -0.012;
  dynamicGroup.add(region);

  const curvePts = [];
  for (let i = 0; i <= 160; i++) {
    const x = 2 * i / 160;
    curvePts.push(new THREE.Vector3(x, safeF(x), 0.025));
  }
  const curve = makeLine(curvePts, BLUE);
  dynamicGroup.add(curve);

  addSegment(dynamicGroup, [2, 0, 0.03], [2, safeF(2), 0.03], AXIS_COLOR);
  addSegment(dynamicGroup, [-0.45, cAxis, 0.01], [7.6, cAxis, 0.01], ROT_RED);

  registerInteractive(region, {
    title: 'Region R',
    tooltip: 'Region revolved about y = c',
    body: 'The shaded region under f(x) and above y = 0 is swept around the red horizontal axis to create washers.'
  });
  registerInteractive(curve, {
    title: 'Generating curve',
    tooltip: 'f(x)',
    body: 'The blue curve determines the outer radius R(x)=f(x)-c of each washer.'
  });
}

function revolutionSurfaceGeometry(radiusFn, xSamples = 121, thetaSamples = 97) {
  const positions = [];
  const indices = [];
  for (let i = 0; i < xSamples; i++) {
    const x = 2 * i / (xSamples - 1);
    const rad = Math.max(0.015, Math.abs(radiusFn(x)));
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(5 + x, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let i = 0; i < xSamples - 1; i++) {
    for (let j = 0; j < thetaSamples - 1; j++) {
      const a = i * thetaSamples + j;
      const b = (i + 1) * thetaSamples + j;
      const cc = (i + 1) * thetaSamples + j + 1;
      const d0 = i * thetaSamples + j + 1;
      indices.push(a, b, d0, b, cc, d0);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function capGeometry(xLocal, innerR, outerR, thetaSamples = 97) {
  const ri = Math.max(0.015, Math.abs(innerR));
  const ro = Math.max(ri + 0.002, Math.abs(outerR));
  const positions = [];
  const indices = [];
  for (let k = 0; k < 2; k++) {
    const rad = k ? ro : ri;
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(5 + xLocal, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let j = 0; j < thetaSamples - 1; j++) {
    const a = j;
    const b = j + 1;
    const cc = thetaSamples + j + 1;
    const d0 = thetaSamples + j;
    indices.push(a, d0, b, b, d0, cc);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function circleLineAtX(xWorld, radius, color, opacity = 0.75) {
  const pts = [];
  const rr = Math.max(0.015, Math.abs(radius));
  for (let j = 0; j <= 128; j++) {
    const th = 2 * Math.PI * j / 128;
    pts.push(new THREE.Vector3(xWorld, cAxis + rr * Math.cos(th), rr * Math.sin(th)));
  }
  return makeLine(pts, color, opacity < 1, opacity);
}

function buildSolid() {
  disposeGroup(solidGroup);

  const rInner = -cAxis;
  const outerMat = new THREE.MeshPhongMaterial({
    color: SOLID_BLUE,
    transparent: true,
    opacity: 0.58,
    side: THREE.DoubleSide,
    shininess: 25,
    depthWrite: false
  });
  const innerMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.78,
    side: THREE.DoubleSide,
    shininess: 18
  });
  const capMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.58,
    side: THREE.DoubleSide,
    shininess: 12
  });

  const outer = new THREE.Mesh(revolutionSurfaceGeometry(x => safeF(x) - cAxis), outerMat);
  const inner = new THREE.Mesh(revolutionSurfaceGeometry(() => rInner), innerMat);
  solidGroup.add(outer, inner);

  const cap0 = new THREE.Mesh(capGeometry(0, rInner, safeF(0) - cAxis), capMat);
  const cap2 = new THREE.Mesh(capGeometry(2, rInner, safeF(2) - cAxis), capMat);
  solidGroup.add(cap0, cap2);

  solidGroup.add(circleLineAtX(5, safeF(0) - cAxis, DARK_GRAY, 0.55));
  solidGroup.add(circleLineAtX(7, safeF(2) - cAxis, DARK_GRAY, 0.85));
  solidGroup.add(circleLineAtX(7, rInner, DARK_GRAY, 0.85));
  solidGroup.add(circleLineAtX(5, rInner, DARK_GRAY, 0.55));

  registerInteractive(outer, {
    title: 'Outer surface',
    tooltip: 'R(x)=f(x)-c',
    body: 'The pale blue-gray surface is swept out by the generating curve. Its distance from the red axis is the outer washer radius.'
  });
  registerInteractive(inner, {
    title: 'Central hole',
    tooltip: 'Inner radius r=0-c',
    body: 'Rotating the lower boundary y=0 about the red axis creates this cylindrical hole.'
  });
}

function annulusDiskGeometry(xWorld, innerR, outerR, thetaSamples = 129) {
  const ri = Math.max(0.015, Math.abs(innerR));
  const ro = Math.max(ri + 0.002, Math.abs(outerR));
  const positions = [];
  const indices = [];
  for (let k = 0; k < 2; k++) {
    const rad = k ? ro : ri;
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(xWorld, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let j = 0; j < thetaSamples - 1; j++) {
    const a = j, b = j + 1, cc = thetaSamples + j + 1, d0 = thetaSamples + j;
    indices.push(a, b, d0, b, cc, d0);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function buildSampleWasher() {
  disposeGroup(sampleGroup);

  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;

  const washerMat = new THREE.MeshPhongMaterial({
    color: HILITE,
    transparent: true,
    opacity: 0.62,
    side: THREE.DoubleSide,
    shininess: 10,
    depthWrite: false
  });
  const ringLeft = new THREE.Mesh(
    new THREE.RingGeometry(Math.max(0.015, Math.abs(r)), Math.max(Math.abs(r) + 0.002, Math.abs(R)), 128),
    new THREE.MeshBasicMaterial({
      color: GRAY,
      transparent: true,
      opacity: 0.68,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  ringLeft.rotation.y = Math.PI / 2;
  ringLeft.position.set(sampleX, cAxis, 0.045);
  sampleGroup.add(ringLeft);

  const disk3 = new THREE.Mesh(annulusDiskGeometry(5 + sampleX, r, R), washerMat);
  sampleGroup.add(disk3);

  addSegment(sampleGroup, [sampleX, 0, 0.075], [sampleX, fx, 0.075], BLUE);
  addSegment(sampleGroup, [sampleX, cAxis, 0.11], [sampleX, fx, 0.11], 0xf3a12b);
  addSegment(sampleGroup, [sampleX + 0.035, cAxis, 0.11], [sampleX + 0.035, 0, 0.11], 0x666666);
  addSegment(sampleGroup, [5 + sampleX, cAxis, 0], [5 + sampleX, fx, 0], 0xf3a12b);
  addSegment(sampleGroup, [5 + sampleX + 0.035, cAxis, 0], [5 + sampleX + 0.035, 0, 0], 0x666666);

  const sampleAxisTick = addSegment(sampleGroup, [sampleX, -0.06, 0.04], [sampleX, 0.06, 0.04], AXIS_COLOR);
  sampleAxisTick.userData.ignore = true;

  registerInteractive(disk3, {
    title: 'Highlighted washer',
    tooltip: 'Washer at selected x',
    body: 'The cross-section has area π(R²−r²), where R=f(x)−c and r=0−c.'
  });
}

function updateLabels() {
  if (!labelsReady) return;
  const fx = safeF(sampleX);
  labelRefs.sampleX.pos.set(sampleX, -0.38, 0.08);
  labelRefs.curve.pos.set(0.62, Math.max(0.45, safeF(0.62) + 0.35), 0.04);
  labelRefs.region.pos.set(1.42, Math.max(1.3, Math.min(3.0, safeF(1.45) * 0.72)), 0.04);
  labelRefs.axis.pos.set(-0.72, cAxis, 0.04);
  labelRefs.axis.div.innerHTML = `y = ${formatNum(cAxis)}`;
  labelRefs.curve.div.innerHTML = currentExpr === 'x^2' ? 'x<sup>2</sup>' : 'f(x)';
}

function formatNum(v) {
  if (!Number.isFinite(v)) return 'NaN';
  const s = Math.abs(v) < 1e-10 ? '0' : v.toFixed(3);
  return s.replace(/\.?0+$/, '');
}

function updateReadouts() {
  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;
  const area = Math.PI * (R * R - r * r);
  document.getElementById('sampleXVal').textContent = sampleX.toFixed(2);
  document.getElementById('readouts').innerHTML =
    `Outer radius R = f(x) − c = <b>${formatNum(R)}</b><br>` +
    `Inner radius r = 0 − c = <b>${formatNum(r)}</b><br>` +
    `Area π(R² − r²) = <b>${formatNum(area)}</b>`;

