  const curvePts = [];
  for (let i = 0; i <= 160; i++) {
    const x = 2 * i / 160;
    curvePts.push(new THREE.Vector3(x, safeF(x), 0.025));
  }
  const curve = makeLine(curvePts, BLUE);
  dynamicGroup.add(curve);

  addSegment(dynamicGroup, [2, 0, 0.03], [2, safeF(2), 0.03], AXIS_COLOR);
