function buildSampleWasher() {
  disposeGroup(sampleGroup);

  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;

  const ringLeft = new THREE.Mesh(
    new THREE.RingGeometry(Math.max(0.012, Math.abs(r)), Math.max(Math.abs(r) + 0.002, Math.abs(R)), 144),
    new THREE.MeshPhongMaterial({
      color: GRAY,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      shininess: 12,
      depthWrite: false
