// representative washer → gray translucent RingGeometry in a plane perpendicular to the x-axis
// sample segment → thin blue vertical Line in the region at the selected x
// 3D outer solid → smooth parametric BufferGeometry surface of revolution, pale blue-gray translucent
// 3D inner hole → gray cylindrical BufferGeometry surface at radius |0-c|
// end caps → gray annular BufferGeometry faces at X=5 and X=7
// rims → dark gray circular Line loops on outer and inner cap boundaries
// highlighted washer → warm gray translucent annular BufferGeometry disk at selected solid X
// radius guides → orange outer-radius and dark-gray inner-radius Line segments on the washer

const AXIS_COLOR = 0x222222;
const TICK_COLOR = 0x222222;
const BLUE = 0x20a7df;
const FILL_BLUE = 0xbfe3f0;
const ROT_RED = 0xff5b63;
const SOLID_BLUE = 0xc8dce5;
const GRAY = 0xbfc3c6;
const DARK_GRAY = 0x666a6d;
const HILITE = 0xd8d0c6;
const ORANGE = 0xf3a12b;

scene.add(new THREE.AmbientLight(0xffffff, 0.86));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.78);
keyLight.position.set(2.5, 7, 7);
scene.add(keyLight);
const softLight = new THREE.DirectionalLight(0xffffff, 0.38);
softLight.position.set(-5, 2.5, -5);
scene.add(softLight);

let currentFn = (x) => x * x;
let currentExpr = 'x^2';
let cAxis = -1;
let sampleX = 1;
let labelsReady = false;
const labelRefs = {};

const staticGroup = new THREE.Group();
const graphGroup = new THREE.Group();
const solidGroup = new THREE.Group();
const sampleGroup = new THREE.Group();
scene.add(staticGroup, graphGroup, solidGroup, sampleGroup);

function disposeGroup(group) {
  while (group.children.length) {
    const obj = group.children.pop();
    obj.traverse?.((o) => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}

function safeF(x) {
  let y;
  try { y = currentFn(x); } catch { y = NaN; }
  return Number.isFinite(y) ? y : 0;
}

function formatNum(v) {
  if (!Number.isFinite(v)) return 'NaN';
  const s = Math.abs(v) < 1e-10 ? '0' : v.toFixed(3);
  return s.replace(/\.?0+$/, '');
}

function makeLine(points, color = AXIS_COLOR, opacity = 1, depthTest = true) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest
  });
  const line = new THREE.Line(geom, mat);
  if (!depthTest) line.renderOrder = 20;
  return line;
}

function addSegment(group, a, b, color = AXIS_COLOR, opacity = 1, depthTest = true) {
  const line = makeLine([new THREE.Vector3(...a), new THREE.Vector3(...b)], color, opacity, depthTest);
  group.add(line);
  return line;
}

function addConeArrow(group, pos, dir, color = AXIS_COLOR, radius = 0.055, height = 0.18) {
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(radius, height, 28),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.set(...pos);
  const q = new THREE.Quaternion();
  q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  cone.quaternion.copy(q);
  group.add(cone);
  return cone;
}

function addThickCurve(points, color, radius = 0.025) {
  const curve = new THREE.CatmullRomCurve3(points);
  const geom = new THREE.TubeGeometry(curve, Math.max(8, points.length * 2), radius, 10, false);
  return new THREE.Mesh(
    geom,
    new THREE.MeshBasicMaterial({ color })
  );
}

function buildStaticAxes() {
  addSegment(staticGroup, [-0.45, 0, 0], [2.55, 0, 0], AXIS_COLOR);
  addConeArrow(staticGroup, [2.63, 0, 0], new THREE.Vector3(1, 0, 0), AXIS_COLOR, 0.065, 0.20);
  addSegment(staticGroup, [0, -2.9, 0], [0, 4.65, 0], AXIS_COLOR);
  addConeArrow(staticGroup, [0, 4.74, 0], new THREE.Vector3(0, 1, 0), AXIS_COLOR, 0.065, 0.20);

  addSegment(staticGroup, [2, -0.09, 0], [2, 0.09, 0], TICK_COLOR);
  addSegment(staticGroup, [-0.09, 4, 0], [0.09, 4, 0], TICK_COLOR);
}

function addRotationArrow(group) {
  const cx = 3.55;
  const r = 0.45;
  const pts = [];
  for (let i = 0; i <= 62; i++) {
    const t = THREE.MathUtils.degToRad(-70 + 270 * i / 62);
    pts.push(new THREE.Vector3(cx, cAxis + r * Math.cos(t), r * Math.sin(t)));
  }
  group.add(makeLine(pts, AXIS_COLOR));
  const end = pts[pts.length - 1];
  const tEnd = THREE.MathUtils.degToRad(200);
  const tangent = new THREE.Vector3(0, -Math.sin(tEnd), Math.cos(tEnd)).normalize();
  addConeArrow(group, [end.x, end.y, end.z], tangent, AXIS_COLOR, 0.047, 0.145);
}

function buildGraph() {
  disposeGroup(graphGroup);

  const n = 160;
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  const curvePts2 = [];
  for (let i = 0; i <= n; i++) {
    const x = 2 * i / n;
    const y = safeF(x);
    shape.lineTo(x, y);
    curvePts2.push(new THREE.Vector3(x, y, 0.035));
  }
  shape.lineTo(2, 0);
  shape.lineTo(0, 0);

  const region = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({
      color: FILL_BLUE,
      transparent: true,
      opacity: 0.55,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  region.position.z = -0.015;
  graphGroup.add(region);

  const curve = addThickCurve(curvePts2, BLUE, 0.027);
  curve.renderOrder = 4;
  graphGroup.add(curve);

  addSegment(graphGroup, [2, 0, 0.04], [2, safeF(2), 0.04], AXIS_COLOR);
  addSegment(graphGroup, [-0.45, cAxis, 0.055], [7.6, cAxis, 0.055], ROT_RED, 1, false);
  addRotationArrow(graphGroup);

  registerInteractive(region, {
    title: 'Region R',
    tooltip: 'Region revolved about y = c',
    body: 'The light-blue region under f(x), above the x-axis, and between x=0 and x=2 is rotated about the red horizontal line.'
  });
  registerInteractive(curve, {
    title: 'Generating curve',
    tooltip: 'f(x)',
    body: 'The blue curve sets the washer outer radius R(x)=f(x)-c.'
  });
}

function revolutionSurfaceGeometry(radiusFn, xSamples = 121, thetaSamples = 97) {
  const positions = [];
  const indices = [];
  for (let i = 0; i < xSamples; i++) {
    const x = 2 * i / (xSamples - 1);
    const rad = Math.max(0.012, Math.abs(radiusFn(x)));
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(5 + x, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let i = 0; i < xSamples - 1; i++) {
    for (let j = 0; j < thetaSamples - 1; j++) {
      const a = i * thetaSamples + j;
      const b = (i + 1) * thetaSamples + j;
      const cc = (i + 1) * thetaSamples + j + 1;
      const d0 = i * thetaSamples + j + 1;
      indices.push(a, b, d0, b, cc, d0);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function annulusGeometryAtX(xWorld, innerR, outerR, thetaSamples = 129) {
  const ri = Math.max(0.012, Math.abs(innerR));
  const ro = Math.max(ri + 0.002, Math.abs(outerR));
  const positions = [];
  const indices = [];
  for (let k = 0; k < 2; k++) {
    const rad = k ? ro : ri;
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(xWorld, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let j = 0; j < thetaSamples - 1; j++) {
    const a = j, b = j + 1, cc = thetaSamples + j + 1, d0 = thetaSamples + j;
    indices.push(a, d0, b, b, d0, cc);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingSphere();
  return geom;
}

function circleLineAtX(xWorld, radius, color = DARK_GRAY, opacity = 0.72) {
  const rr = Math.max(0.012, Math.abs(radius));
  const pts = [];
  for (let j = 0; j <= 144; j++) {
    const th = 2 * Math.PI * j / 144;
    pts.push(new THREE.Vector3(xWorld, cAxis + rr * Math.cos(th), rr * Math.sin(th)));
  }
  return makeLine(pts, color, opacity);
}

function buildSolid() {
  disposeGroup(solidGroup);

  const rInner = -cAxis;
  const outerMat = new THREE.MeshPhongMaterial({
    color: SOLID_BLUE,
    transparent: true,
    opacity: 0.60,
    side: THREE.DoubleSide,
    shininess: 20,
    depthWrite: false
  });
  const innerMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.82,
    side: THREE.DoubleSide,
    shininess: 16,
    depthWrite: false
  });
  const capMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.66,
    side: THREE.DoubleSide,
    shininess: 12,
    depthWrite: false
  });

  const outer = new THREE.Mesh(revolutionSurfaceGeometry(x => safeF(x) - cAxis), outerMat);
  const inner = new THREE.Mesh(revolutionSurfaceGeometry(() => rInner), innerMat);
  outer.renderOrder = 2;
  inner.renderOrder = 3;
  solidGroup.add(outer, inner);

  const cap0 = new THREE.Mesh(annulusGeometryAtX(5, rInner, safeF(0) - cAxis), capMat);
  const cap2 = new THREE.Mesh(annulusGeometryAtX(7, rInner, safeF(2) - cAxis), capMat);
  cap0.renderOrder = 4;
  cap2.renderOrder = 4;
  solidGroup.add(cap0, cap2);

  solidGroup.add(circleLineAtX(5, safeF(0) - cAxis, DARK_GRAY, 0.48));
  solidGroup.add(circleLineAtX(5, rInner, DARK_GRAY, 0.48));
  solidGroup.add(circleLineAtX(7, safeF(2) - cAxis, DARK_GRAY, 0.86));
  solidGroup.add(circleLineAtX(7, rInner, DARK_GRAY, 0.86));

  registerInteractive(outer, {
    title: 'Outer parabolic surface',
    tooltip: 'R(x)=f(x)-c',
    body: 'Rotating the blue curve about the red axis sweeps out this pale outer surface.'
  });
  registerInteractive(inner, {
    title: 'Cylindrical hole',
    tooltip: 'Inner radius r=0-c',
    body: 'Rotating the x-axis boundary y=0 about y=c creates the gray cylindrical hole through the solid.'
  });
}

function buildSampleWasher() {
  disposeGroup(sampleGroup);

  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;

  const ringLeft = new THREE.Mesh(
    new THREE.RingGeometry(Math.max(0.012, Math.abs(r)), Math.max(Math.abs(r) + 0.002, Math.abs(R)), 144),
    new THREE.MeshPhongMaterial({
      color: GRAY,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      shininess: 12,
      depthWrite: false
    })
  );
  ringLeft.rotation.y = Math.PI / 2;
  ringLeft.position.set(sampleX, cAxis, 0.06);
  ringLeft.renderOrder = 7;
  sampleGroup.add(ringLeft);

  const disk3 = new THREE.Mesh(
    annulusGeometryAtX(5 + sampleX, r, R),
    new THREE.MeshPhongMaterial({
      color: HILITE,
      transparent: true,
      opacity: 0.62,
      side: THREE.DoubleSide,
      shininess: 10,
      depthWrite: false
    })
  );
  disk3.renderOrder = 6;
  sampleGroup.add(disk3);

  addSegment(sampleGroup, [sampleX, 0, 0.10], [sampleX, fx, 0.10], BLUE);
  addSegment(sampleGroup, [sampleX, cAxis, 0.14], [sampleX, fx, 0.14], ORANGE);
  addSegment(sampleGroup, [sampleX + 0.045, cAxis, 0.14], [sampleX + 0.045, 0, 0.14], DARK_GRAY);
  addSegment(sampleGroup, [5 + sampleX, cAxis, 0], [5 + sampleX, fx, 0], ORANGE);
  addSegment(sampleGroup, [5 + sampleX + 0.045, cAxis, 0], [5 + sampleX + 0.045, 0, 0], DARK_GRAY);
  addSegment(sampleGroup, [sampleX, -0.06, 0.08], [sampleX, 0.06, 0.08], AXIS_COLOR);

  registerInteractive(disk3, {
    title: 'Highlighted washer',
    tooltip: 'Washer at selected x',
    body: 'This cross-section has area π(R²−r²), where R=f(x)−c and r=0−c.'
  });
}

function approximateVolume() {
  const N = 400;
  const h = 2 / N;
  let sum = 0;
  for (let i = 0; i <= N; i++) {
    const x = i * h;
    const R = safeF(x) - cAxis;
    const r = -cAxis;
    const A = Math.PI * (R * R - r * r);
    const w = (i === 0 || i === N) ? 1 : (i % 2 ? 4 : 2);
    sum += w * A;
  }
  return sum * h / 3;
}

function updateReadouts() {
  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;
  const area = Math.PI * (R * R - r * r);
  document.getElementById('sampleXVal').textContent = sampleX.toFixed(2);
  document.getElementById('readouts').innerHTML =
    `Outer radius R = f(x) − c = <b>${formatNum(R)}</b><br>` +
    `Inner radius r = 0 − c = <b>${formatNum(r)}</b><br>` +
    `Area π(R² − r²) = <b>${formatNum(area)}</b><br>` +
    `Volume ≈ ∫₀²A(x)dx = <b>${formatNum(approximateVolume())}</b>`;

  let crosses = false;
  for (let i = 0; i <= 100; i++) {
    const x = 2 * i / 100;
    const y = safeF(x);
    if (cAxis >= Math.min(0, y) && cAxis <= Math.max(0, y)) crosses = true;
  }
  const notes = [];
  if (R < 0 || r < 0) notes.push('Warning: one textbook signed radius is negative.');
  if (crosses) notes.push('Warning: the axis crosses the region, so simple washers may overlap.');
  document.getElementById('warn').textContent = notes.join(' ');
}

function updateLabels() {
  if (!labelsReady) return;
  labelRefs.sampleX.pos.set(sampleX, -0.38, 0.12);
  labelRefs.curve.pos.set(0.62, Math.max(0.55, safeF(0.62) + 0.35), 0.07);
  labelRefs.region.pos.set(1.42, Math.max(1.15, Math.min(3.15, safeF(1.45) * 0.72)), 0.07);
  labelRefs.axis.pos.set(-0.72, cAxis, 0.08);
  labelRefs.axis.div.innerHTML = `y = ${formatNum(cAxis)}`;
  labelRefs.curve.div.innerHTML = currentExpr.replace(/\^2/g, '<sup>2</sup>') === 'x<sup>2</sup>' ? 'x<sup>2</sup>' : 'f(x)';
}

function rebuildAll() {
  buildGraph();
  buildSolid();
  buildSampleWasher();
  updateLabels();
  updateReadouts();
}

buildStaticAxes();
buildGraph();
buildSolid();
buildSampleWasher();

setCameraView({
  projection: 'perspective',
  azimuthDeg: 25,
  elevationDeg: 6,
  rollDeg: 0,
  heightFraction: 0.68
});

labelRefs.xAxis = addLabel('<i>x</i>', new THREE.Vector3(2.56, 0.27, 0), { fontSize: '22px' });
labelRefs.yAxis = addLabel('<i>y</i>', new THREE.Vector3(0.20, 4.67, 0), { fontSize: '22px' });
labelRefs.origin = addLabel('0', new THREE.Vector3(-0.16, -0.34, 0), { fontSize: '22px' });
labelRefs.x2Tick = addLabel('2', new THREE.Vector3(2, -0.38, 0), { fontSize: '21px' });
labelRefs.y4Tick = addLabel('4', new THREE.Vector3(-0.19, 4, 0), { fontSize: '21px' });
labelRefs.curve = addLabel('x<sup>2</sup>', new THREE.Vector3(0.62, 1.05, 0.07), { fontSize: '22px' });
labelRefs.region = addLabel('<i>R</i>', new THREE.Vector3(1.38, 2.0, 0.07), { fontSize: '24px' });
labelRefs.axis = addLabel('y = −1', new THREE.Vector3(-0.72, -1, 0.08), { fontSize: '22px' });
labelRefs.sampleX = addLabel('<i>x</i>', new THREE.Vector3(sampleX, -0.38, 0.12), { fontSize: '22px' });
labelsReady = true;
updateLabels();
updateReadouts();

bindEquationInput('generatingCurve', (fn, src) => {
  currentFn = fn;
  currentExpr = (src || '').trim() || 'f(x)';
  rebuildAll();
}, { variables: ['x'] });

bindEquationInput('axisOfRotation', (fn) => {
  const a = fn(0);
  const b = fn(2);
  if (!Number.isFinite(a)) throw new Error('Axis value must be a finite number.');
  if (Math.abs(a - b) > 1e-8) throw new Error('Use a constant axis value, not an x-dependent expression.');
  cAxis = a;
  rebuildAll();
}, { variables: [] });

document.getElementById('sampleX').addEventListener('input', (e) => {
  sampleX = Number(e.target.value);
  buildSampleWasher();
  updateLabels();
  updateReadouts();
});

const steps = [
  {
    title: 'Middle washer',
    narration: 'At x = 1 with f(x)=x² and c=-1, the outer radius is 2 and the inner radius is 1. The washer area is π(2² − 1²) = 3π.',
    state: { sampleX: 1 }
  },
  {
    title: 'Thin washer near the start',
    narration: 'Near x = 0 the curve is close to the x-axis, so the outer and inner radii are nearly equal. The washer has very little area.',
    state: { sampleX: 0.25 }
  },
  {
    title: 'Large washer at x = 2',
    narration: 'At x = 2 the outer radius is 5 while the inner radius remains 1. This large final washer explains the flared end of the solid.',
    state: { sampleX: 2 }
  }
];

let currentStep = 0;
let tweenId = null;

function renderStepText() {
  const st = steps[currentStep];
  document.getElementById('stepBox').innerHTML = `<b>${currentStep + 1}. ${st.title}</b><br>${st.narration}`;
}

function setSampleXAnimated(target) {
  if (tweenId) cancelAnimationFrame(tweenId);
  const start = sampleX;
  const t0 = performance.now();
  const dur = 550;
  function tick(now) {
    const u = Math.min(1, (now - t0) / dur);
    const e = u * u * (3 - 2 * u);
    sampleX = start + (target - start) * e;
    document.getElementById('sampleX').value = sampleX;
    buildSampleWasher();
    updateLabels();
    updateReadouts();
    if (u < 1) tweenId = requestAnimationFrame(tick);
  }
  tweenId = requestAnimationFrame(tick);
}

window.goToStep = function goToStep(i) {
  currentStep = ((i % steps.length) + steps.length) % steps.length;
  renderStepText();
  setSampleXAnimated(steps[currentStep].state.sampleX);
};

document.getElementById('prevStep').addEventListener('click', () => window.goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => window.goToStep(currentStep + 1));
renderStepText();
