const AXIS_COLOR = 0x222222;
const BLUE = 0x20a7df;
const FILL_BLUE = 0xbfe3f0;
const ROT_RED = 0xff5b63;
const SOLID_BLUE = 0xc8dce5;
const GRAY = 0xbfc3c6;
const DARK_GRAY = 0x777a7d;
const RIM_GRAY = 0x9ca1a5;
const HILITE = 0xd8d0c6;
const ORANGE = 0xf3a12b;

scene.add(new THREE.AmbientLight(0xffffff, 0.82));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.82);
keyLight.position.set(1.5, 7, 7);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.36);
fillLight.position.set(-4, 2.5, -5);
scene.add(fillLight);

let currentFn = (x) => x * x;
let currentExpr = 'x^2';
let cAxis = -1;
let sampleX = 1;
let labelsReady = false;
const labelRefs = {};

const staticGroup = new THREE.Group();
const graphGroup = new THREE.Group();
const solidGroup = new THREE.Group();
const sampleGroup = new THREE.Group();
scene.add(staticGroup, graphGroup, solidGroup, sampleGroup);

function disposeGroup(group) {
  while (group.children.length) {
    const obj = group.children.pop();
    obj.traverse?.((o) => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}

function safeF(x) {
  let y;
  try { y = currentFn(x); } catch { y = NaN; }
  return Number.isFinite(y) ? y : 0;
}

function formatNum(v) {
  if (!Number.isFinite(v)) return 'NaN';
  const s = Math.abs(v) < 1e-10 ? '0' : v.toFixed(3);
  return s.replace(/\.?0+$/, '');
}

function makeLine(points, color = AXIS_COLOR, opacity = 1, depthTest = true) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest
  });
  const line = new THREE.Line(geom, mat);
  if (!depthTest) line.renderOrder = 30;
  return line;
}

function addSegment(group, a, b, color = AXIS_COLOR, opacity = 1, depthTest = true) {
  const line = makeLine([new THREE.Vector3(...a), new THREE.Vector3(...b)], color, opacity, depthTest);
  group.add(line);
  return line;
}

function addConeArrow(group, pos, dir, color = AXIS_COLOR, radius = 0.055, height = 0.18) {
  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(radius, height, 28),
    new THREE.MeshBasicMaterial({ color })
  );
  cone.position.set(...pos);
  const q = new THREE.Quaternion();
  q.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  cone.quaternion.copy(q);
  group.add(cone);
  return cone;
}

function addThickCurve(points, color, radius = 0.026) {
  const curve = new THREE.CatmullRomCurve3(points, false, 'centripetal');
  const geom = new THREE.TubeGeometry(curve, Math.max(32, points.length * 2), radius, 10, false);
  return new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color }));
}

