  addSegment(staticGroup, [0, -2.9, 0], [0, 4.65, 0], AXIS_COLOR);
  addConeArrow(staticGroup, [0, 4.75, 0], new THREE.Vector3(0, 1, 0), AXIS_COLOR, 0.065, 0.20);

  addSegment(staticGroup, [2, -0.095, 0], [2, 0.095, 0], AXIS_COLOR);
  addSegment(staticGroup, [-0.095, 4, 0], [0.095, 4, 0], AXIS_COLOR);
}

function addRotationArrow(group) {
  const cx = 3.55;
  const r = 0.43;
  const pts = [];
  for (let i = 0; i <= 70; i++) {
    const t = THREE.MathUtils.degToRad(-72 + 272 * i / 70);
    pts.push(new THREE.Vector3(cx, cAxis + r * Math.cos(t), r * Math.sin(t)));
  }
  group.add(makeLine(pts, AXIS_COLOR, 1, true));
  const end = pts[pts.length - 1];
  const tEnd = THREE.MathUtils.degToRad(200);
  const tangent = new THREE.Vector3(0, -Math.sin(tEnd), Math.cos(tEnd)).normalize();
  addConeArrow(group, [end.x, end.y, end.z], tangent, AXIS_COLOR, 0.045, 0.14);
}

function buildGraph() {
  disposeGroup(graphGroup);

  const n = 180;
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  const curvePts = [];
  for (let i = 0; i <= n; i++) {
    const x = 2 * i / n;
    const y = safeF(x);
    shape.lineTo(x, y);
    curvePts.push(new THREE.Vector3(x, y, 0.035));
  }
  shape.lineTo(2, 0);
  shape.lineTo(0, 0);

  const region = new THREE.Mesh(
    new THREE.ShapeGeometry(shape),
    new THREE.MeshBasicMaterial({
      color: FILL_BLUE,
      transparent: true,
      opacity: 0.55,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  region.position.z = -0.012;
  region.renderOrder = 1;
  graphGroup.add(region);

  const curve = addThickCurve(curvePts, BLUE, 0.027);
  curve.renderOrder = 5;
  graphGroup.add(curve);

  addSegment(graphGroup, [2, 0, 0.045], [2, safeF(2), 0.045], AXIS_COLOR, 1, true);
  addSegment(graphGroup, [-0.45, cAxis, 0.055], [7.6, cAxis, 0.055], ROT_RED, 1, false);
  addRotationArrow(graphGroup);

  registerInteractive(region, {
    title: 'Region R',
    tooltip: 'Region revolved about y = c',
    body: 'The light-blue region under f(x), above the x-axis, and between x=0 and x=2 is rotated about the red horizontal line.'
  });
  registerInteractive(curve, {
    title: 'Generating curve',
    tooltip: 'f(x)',
    body: 'The blue curve determines the outer washer radius R(x)=f(x)-c.'
  });
}

function revolutionSurfaceGeometry(radiusFn, xSamples = 124, thetaSamples = 100) {
  const positions = [];
  const indices = [];
  for (let i = 0; i < xSamples; i++) {
    const x = 2 * i / (xSamples - 1);
    const rad = Math.max(0.012, Math.abs(radiusFn(x)));
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(5 + x, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let i = 0; i < xSamples - 1; i++) {
    for (let j = 0; j < thetaSamples - 1; j++) {
      const a = i * thetaSamples + j;
      const b = (i + 1) * thetaSamples + j;
      const cc = (i + 1) * thetaSamples + j + 1;
      const d0 = i * thetaSamples + j + 1;
      indices.push(a, b, d0, b, cc, d0);
    }
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function annulusGeometryAtX(xWorld, innerR, outerR, thetaSamples = 144) {
  const ri = Math.max(0.012, Math.abs(innerR));
  const ro = Math.max(ri + 0.002, Math.abs(outerR));
  const positions = [];
  const indices = [];
  for (let k = 0; k < 2; k++) {
    const rad = k ? ro : ri;
    for (let j = 0; j < thetaSamples; j++) {
      const th = 2 * Math.PI * j / (thetaSamples - 1);
      positions.push(xWorld, cAxis + rad * Math.cos(th), rad * Math.sin(th));
    }
  }
  for (let j = 0; j < thetaSamples - 1; j++) {
    const a = j;
    const b = j + 1;
    const cc = thetaSamples + j + 1;
    const d0 = thetaSamples + j;
    indices.push(a, d0, b, b, d0, cc);
  }
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geom.setIndex(indices);
  geom.computeVertexNormals();
  geom.computeBoundingBox();
  geom.computeBoundingSphere();
  return geom;
}

function circleLineAtX(xWorld, radius, color = RIM_GRAY, opacity = 0.75) {
  const rr = Math.max(0.012, Math.abs(radius));
  const pts = [];
  for (let j = 0; j <= 160; j++) {
    const th = 2 * Math.PI * j / 160;
    pts.push(new THREE.Vector3(xWorld, cAxis + rr * Math.cos(th), rr * Math.sin(th)));
  }
  return makeLine(pts, color, opacity, true);
}

function buildSolid() {
  disposeGroup(solidGroup);

  const rInner = -cAxis;
  const outerMat = new THREE.MeshPhongMaterial({
    color: SOLID_BLUE,
    transparent: true,
    opacity: 0.58,
    side: THREE.DoubleSide,
    shininess: 18,
    depthWrite: false
  });
  const innerMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.78,
    side: THREE.DoubleSide,
    shininess: 14,
    depthWrite: false
  });
  const capMat = new THREE.MeshPhongMaterial({
    color: GRAY,
    transparent: true,
    opacity: 0.68,
    side: THREE.DoubleSide,
    shininess: 12,
    depthWrite: false
  });

  const outer = new THREE.Mesh(revolutionSurfaceGeometry(x => safeF(x) - cAxis), outerMat);
  const inner = new THREE.Mesh(revolutionSurfaceGeometry(() => rInner), innerMat);
  outer.renderOrder = 2;
  inner.renderOrder = 3;
  solidGroup.add(outer, inner);

  const cap0 = new THREE.Mesh(annulusGeometryAtX(5, rInner, safeF(0) - cAxis), capMat);
  const cap2 = new THREE.Mesh(annulusGeometryAtX(7, rInner, safeF(2) - cAxis), capMat);
  cap0.renderOrder = 4;
  cap2.renderOrder = 4;
  solidGroup.add(cap0, cap2);

  solidGroup.add(circleLineAtX(5, safeF(0) - cAxis, RIM_GRAY, 0.52));
  solidGroup.add(circleLineAtX(5, rInner, RIM_GRAY, 0.52));
  solidGroup.add(circleLineAtX(7, safeF(2) - cAxis, RIM_GRAY, 0.90));
  solidGroup.add(circleLineAtX(7, rInner, RIM_GRAY, 0.90));

  registerInteractive(outer, {
    title: 'Outer parabolic surface',
    tooltip: 'R(x)=f(x)-c',
    body: 'Rotating the blue curve about the red axis sweeps out this pale outer surface.'
  });
  registerInteractive(inner, {
    title: 'Cylindrical hole',
    tooltip: 'Inner radius r=0-c',
    body: 'Rotating the x-axis boundary y=0 about y=c creates the gray cylindrical hole through the solid.'
  });
}

function buildSampleWasher() {
  disposeGroup(sampleGroup);

  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;
  const ringInner = Math.max(0.012, Math.abs(r));
  const ringOuter = Math.max(ringInner + 0.002, Math.abs(R));

  const ringLeft = new THREE.Mesh(
    new THREE.RingGeometry(ringInner, ringOuter, 144),
    new THREE.MeshPhongMaterial({
      color: GRAY,
      transparent: true,
      opacity: 0.72,
      side: THREE.DoubleSide,
      shininess: 10,
      depthWrite: false
    })
  );
  ringLeft.rotation.y = Math.PI / 2;
  ringLeft.position.set(sampleX, cAxis, 0.07);
  ringLeft.renderOrder = 8;
  sampleGroup.add(ringLeft);

  const disk3 = new THREE.Mesh(
    annulusGeometryAtX(5 + sampleX, r, R),
    new THREE.MeshPhongMaterial({
      color: HILITE,
      transparent: true,
      opacity: 0.64,
      side: THREE.DoubleSide,
      shininess: 10,
      depthWrite: false
    })
  );
  disk3.renderOrder = 7;
  sampleGroup.add(disk3);

  addSegment(sampleGroup, [sampleX, 0, 0.11], [sampleX, fx, 0.11], BLUE, 1, true);
  addSegment(sampleGroup, [sampleX, cAxis, 0.16], [sampleX, fx, 0.16], ORANGE, 1, false);
  addSegment(sampleGroup, [sampleX + 0.045, cAxis, 0.16], [sampleX + 0.045, 0, 0.16], DARK_GRAY, 1, false);

  addSegment(sampleGroup, [5 + sampleX, cAxis, 0], [5 + sampleX, fx, 0], ORANGE, 1, false);
  addSegment(sampleGroup, [5 + sampleX + 0.045, cAxis, 0], [5 + sampleX + 0.045, 0, 0], DARK_GRAY, 1, false);
  addSegment(sampleGroup, [sampleX, -0.065, 0.11], [sampleX, 0.065, 0.11], AXIS_COLOR, 1, true);

  registerInteractive(disk3, {
    title: 'Highlighted washer',
    tooltip: 'Washer at selected x',
    body: 'This cross-section has area π(R²−r²), where R=f(x)−c and r=0−c.'
  });
}

function approximateVolume() {
  const N = 400;
  const h = 2 / N;
  let sum = 0;
  for (let i = 0; i <= N; i++) {
    const x = i * h;
    const R = safeF(x) - cAxis;
    const r = -cAxis;
    const A = Math.PI * (R * R - r * r);
    const w = (i === 0 || i === N) ? 1 : (i % 2 ? 4 : 2);
    sum += w * A;
  }
  return sum * h / 3;
}

function updateReadouts() {
  const fx = safeF(sampleX);
  const R = fx - cAxis;
  const r = -cAxis;
  const area = Math.PI * (R * R - r * r);
  document.getElementById('sampleXVal').textContent = sampleX.toFixed(2);
  document.getElementById('readouts').innerHTML =
    `Outer radius R = f(x) − c = <b>${formatNum(R)}</b><br>` +
    `Inner radius r = 0 − c = <b>${formatNum(r)}</b><br>` +
    `Area π(R² − r²) = <b>${formatNum(area)}</b><br>` +
    `Volume ∫₀²π(R²−r²)dx ≈ <b>${formatNum(approximateVolume())}</b>`;

  let crosses = false;
  for (let i = 0; i <= 120; i++) {
    const x = 2 * i / 120;
    const y = safeF(x);
    if (cAxis >= Math.min(0, y) && cAxis <= Math.max(0, y)) crosses = true;
  }
  const notes = [];
  if (R < 0 || r < 0) notes.push('Warning: a signed textbook radius is negative.');
  if (crosses) notes.push('Warning: the axis crosses the region, so simple washers may overlap.');
  document.getElementById('warn').textContent = notes.join(' ');
}

function htmlExprLabel(src) {
  const trimmed = (src || '').trim();
  if (trimmed === 'x^2' || trimmed === 'x*x') return '<i>x</i><sup>2</sup>';
  return '<i>f</i>(<i>x</i>)';
}

function updateLabels() {
  if (!labelsReady) return;
  labelRefs.sampleX.pos.set(sampleX, -0.38, 0.12);
  labelRefs.axis.pos.set(-0.82, cAxis, 0.08);
  labelRefs.axis.div.innerHTML = `y = ${formatNum(cAxis)}`;
  labelRefs.curve.div.innerHTML = htmlExprLabel(currentExpr);
  labelRefs.curve.pos.set(-0.26, 1.20, 0.08);
  labelRefs.region.pos.set(1.34, Math.max(0.7, Math.min(2.25, safeF(1.45) * 0.60)), 0.08);
}

function rebuildAll() {
  buildGraph();
  buildSolid();
  buildSampleWasher();
  updateLabels();
  updateReadouts();
}

buildStaticAxes();
