bindEquationInput('axisOfRotation', (fn) => {
  const a = fn(0);
  const b = fn(2);
  if (!Number.isFinite(a)) throw new Error('Axis value must be a finite number.');
  if (Math.abs(a - b) > 1e-8) throw new Error('Use a constant axis value, not an x-dependent expression.');
  cAxis = a;
  rebuildAll();
}, { variables: [] });

