const steps = [
  {
    title: 'Middle washer',
    narration: 'At x = 1 with f(x)=x² and c=-1, the outer radius is 2 and the inner radius is 1. The washer area is π(2² − 1²) = 3π.',
    state: { sampleX: 1 }
  },
  {
    title: 'Thin washer near the start',
    narration: 'Near x = 0 the curve is close to the x-axis, so the outer and inner radii are nearly equal. The washer has very little area.',
    state: { sampleX: 0.25 }
  },
  {
