    narration: 'At x = 2 the outer radius is 5 while the inner radius remains 1. This large final washer explains the flared end of the solid.',
    state: { sampleX: 2 }
  }
];

let currentStep = 0;
let tweenId = null;

function renderStepText() {
  const st = steps[currentStep];
  document.getElementById('stepBox').innerHTML = `<b>${currentStep + 1}. ${st.title}</b><br>${st.narration}`;
}

function setSampleXAnimated(target) {
  if (tweenId) cancelAnimationFrame(tweenId);
  const start = sampleX;
  const t0 = performance.now();
  const dur = 550;
  function tick(now) {
    const u = Math.min(1, (now - t0) / dur);
    const e = u * u * (3 - 2 * u);
    sampleX = start + (target - start) * e;
    document.getElementById('sampleX').value = sampleX;
    buildSampleWasher();
    updateLabels();
    updateReadouts();
    if (u < 1) tweenId = requestAnimationFrame(tick);
  }
  tweenId = requestAnimationFrame(tick);
}

window.goToStep = function goToStep(i) {
  currentStep = ((i % steps.length) + steps.length) % steps.length;
  renderStepText();
  setSampleXAnimated(steps[currentStep].state.sampleX);
};

document.getElementById('prevStep').addEventListener('click', () => window.goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => window.goToStep(currentStep + 1));
renderStepText();
